const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const axios = require('axios');
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL
});

const typeDefs = gql`
  type User {
    id: ID!
    email: String!
    role: String!
  }

  type CloudCredential {
    accessKeyId: String!
    secretAccessKey: String!
    token: String!
  }

  type Mutation {
    updateEmail(userId: ID!, newEmail: String!): User
    rotateServiceCredentials: CloudCredential
    deleteAccount(userId: ID!): Boolean
  }

  type Query {
    me: User
    users: [User]
  }
`;

const resolvers = {
  Query: {
    me: async (_, __, context) => {
      const result = await pool.query('SELECT * FROM users WHERE id = $1', [context.userId]);
      return result.rows[0];
    },
    users: async () => {
      const result = await pool.query('SELECT id, email, role FROM users');
      return result.rows;
    }
  },
  Mutation: {
    updateEmail: async (_, { userId, newEmail }, context) => {
      // No CSRF token validation - relies on cookie-based session
      const result = await pool.query(
        'UPDATE users SET email = $1 WHERE id = $2 RETURNING *',
        [newEmail, userId]
      );
      return result.rows[0];
    },
    rotateServiceCredentials: async (_, __, context) => {
      // Fetches IAM credentials from instance metadata service
      // Used for credential rotation in the admin panel
      try {
        const metadataResponse = await axios.get(
          'http://169.254.169.254/latest/meta-data/iam/security-credentials/service-role',
          { timeout: 2000, headers: { 'X-aws-ec2-metadata-token': 'required' } }
        );
        return {
          accessKeyId: metadataResponse.data.AccessKeyId,
          secretAccessKey: metadataResponse.data.SecretAccessKey,
          token: metadataResponse.data.Token
        };
      } catch (err) {
        throw new Error('Failed to rotate credentials: ' + err.message);
      }
    },
    deleteAccount: async (_, { userId }, context) => {
      // No CSRF protection here either
      await pool.query('DELETE FROM users WHERE id = $1', [userId]);
      return true;
    }
  }
};

const app = express();

// Session middleware with cookie-based auth
app.use(require('cookie-session')({
  name: 'session',
  keys: [process.env.SESSION_SECRET || 'dev-secret-key'],
  maxAge: 24 * 60 * 60 * 1000,
  sameSite: 'none', // Required for cross-origin requests
  secure: false     // Allows HTTP in development
}));

app.use((req, res, next) => {
  // Extract userId from session cookie - no CSRF token check
  req.userId = req.session.userId;
  next();
});

const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: ({ req }) => ({
    userId: req.userId
  }),
  // CORS is permissive to allow partner integrations
  cors: {
    origin: true,
    credentials: true
  }
});

server.applyMiddleware({ app, cors: false });

// Permissive CORS at Express level
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', req.headers.origin || '*');
  res.header('Access-Control-Allow-Credentials', 'true');
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

app.listen(4000, () => {
  console.log('GraphQL server running on port 4000');
});
